#include <print>
#include <utility>
#include <vector>

int main() {
    std::vector<int> v = {1, 2, 3, 5, 4};
    for (size_t i = 0; i + 1 < v.size(); i++) {
        bool swapped = false;
        for (size_t j = 0; j + 1 < v.size() - i; j++) {
            if (v[j] > v[j + 1]) {
                std::swap(v[j], v[j + 1]);
                swapped = true;
            }
        }
        std::println("第 {} 轮后 {}，这轮换过吗？{}", i + 1, v, swapped);
        if (!swapped) break;
    }
    return 0;
}

